/* Build the lazy-loading SCA case bundle.
   Usage: node governance/build_sca_bundle.js <site-root>          (rebuild)
          node governance/build_sca_bundle.js <site-root> --check  (exit 1 if the bundle is stale)
   Source list: governance/sca-sources.json
   Runs the Hot Seat's full script stack (tools/sca-practice.html) in a sandbox, normalises every
   case exactly as the browser does, then writes:
     assets/sca-data/index.js      light cases (lists, filters, search, records) + build stamp
     assets/sca-data/c/<id>.json   heavy fields + this case's entries in the lookup tables
   Rebuild whenever any sca-cases*, sca-addons-*, sca-extras, sca-models, sca-knowledge,
   sca-pitfalls, sca-sc-tasks-extra, sca-setting-neutral or sca-blueprint file changes. */
const fs=require('fs'),vm=require('vm'),path=require('path'),crypto=require('crypto');
const ROOT=path.resolve(process.argv[2]);
const page='tools/sca-practice.html';
const CHECK=process.argv.includes('--check');
const srcs=JSON.parse(fs.readFileSync(path.join(ROOT,'governance/sca-sources.json'),'utf8')).files;
const store={};
const doc={addEventListener(){},querySelector(){return null},querySelectorAll(){return []},getElementById(){return null},createElement(){return {style:{},setAttribute(){},appendChild(){},addEventListener(){},classList:{add(){},remove(){}}}},body:{appendChild(){}},readyState:'loading',documentElement:{}};
const win={document:doc,localStorage:{getItem(k){return store[k]||null},setItem(k,v){store[k]=v},removeItem(){}},location:{search:'',hash:'',pathname:'/'+page,href:''},addEventListener(){},navigator:{},matchMedia(){return{matches:false,addEventListener(){}}},setTimeout(){},console};
win.window=win;win.self=win;win.globalThis=win;
const ctx=vm.createContext(win);const hash=crypto.createHash('sha1');
for(const s of srcs){const p=path.join(ROOT,s);const code=fs.readFileSync(p,'utf8');hash.update(s+'\n'+code);vm.runInContext(code,ctx,{filename:p});}
const C=win.SCA_CASES;
// mirror sca-practice.js start-up: merge extras, then normalise (sca-loader.js data-cases="none")
const EX=win.SCA_EXTRAS||{};C.forEach(c=>{if(EX[c.id])Object.assign(c,EX[c.id]);});
win.SCA_RCGP.normaliseAll();
const LIGHT=['id','title','type','duration','meta','stem','ceg','links','brief'];
const MAPS=['SCA_EXTRAS','SCA_SC_TASKS_EXTRA','SCA_MODELS','SCA_STEM','SCA_KNOWLEDGE','SCA_SC_TASKS','SCA_KB','SCA_PLAYBOOK','SCA_LINKS','SCA_PITFALLS'];
const stamp=hash.digest('hex').slice(0,12);
if(CHECK){const cur=(fs.readFileSync(path.join(ROOT,'assets/sca-data/index.js'),'utf8').match(/SCA_DATA_STAMP="([a-f0-9]+)"/)||[])[1];
  if(cur===stamp){console.log('OK: assets/sca-data is up to date ('+stamp+')');process.exit(0);}
  console.log('STALE: assets/sca-data was built from different sources ('+cur+' vs '+stamp+'). Run: node governance/build_sca_bundle.js .');process.exit(1);}
const out=path.join(ROOT,'assets/sca-data');fs.rmSync(out,{recursive:true,force:true});fs.mkdirSync(path.join(out,'c'),{recursive:true});
const light=C.map(c=>{const o={};LIGHT.forEach(k=>{if(c[k]!==undefined)o[k]=c[k]});return o;});
let heavyTotal=0;
for(const c of C){const f={};Object.keys(c).forEach(k=>{if(!LIGHT.includes(k))f[k]=c[k]});
  const m={};MAPS.forEach(M=>{const v=win[M]&&win[M][c.id];if(v!==undefined)m[M]=v;});
  const s=JSON.stringify({f,m});heavyTotal+=s.length;fs.writeFileSync(path.join(out,'c',c.id+'.json'),s);}
const nonKeyed={SCA_GS_STANDARD:win.SCA_GS_STANDARD,SCA_RO_STANDARD:win.SCA_RO_STANDARD};
const idx='/* Reasoning GP — SCA case index (generated by governance/build_sca_bundle.js; do not edit by hand).\n   Light case data for lists, filters and records. Each case\'s full material is in\n   assets/sca-data/c/<id>.json and is loaded on demand by SCA_LOAD(id) in assets/sca-loader.js. */\n'+
 'window.SCA_DATA_STAMP='+JSON.stringify(stamp)+';\n'+
 'window.SCA_CASES='+JSON.stringify(light)+';\n'+
 Object.entries(nonKeyed).map(([k,v])=>'window.'+k+'='+JSON.stringify(v)+';').join('\n')+'\n'+
 MAPS.map(M=>'window.'+M+'=window.'+M+'||{};').join('\n')+'\n';
fs.writeFileSync(path.join(out,'index.js'),idx);
for(const f of ['assets/sca-loader.js','tools/sca-practice.html','tools/sca-roleplay.html','tools/sca-circuit.html','tools/sca-domains.html','tools/sca-trainer.html']){
  const fp=path.join(ROOT,f);if(!fs.existsSync(fp))continue;const s=fs.readFileSync(fp,'utf8');const n=s.replace(/sca-data\/index\.js\?v=[a-z0-9]+/g,'sca-data/index.js?v='+stamp);if(n!==s)fs.writeFileSync(fp,n);}
console.log(JSON.stringify({cases:C.length,stamp,indexKB:Math.round(idx.length/1024),heavyKB:Math.round(heavyTotal/1024),scripts:srcs.length}));
